if __name__ == '__main__':
    out = os.path.join(os.path.dirname(__file__), '..', 'public', 'i18n')
    os.makedirs(out, exist_ok=True)
    rows = {k: v for k, v in ROWS.items() if v}
    for k, v in rows.items():
        assert len(v) == len(LANGS), k
    for i, code in enumerate(LANGS):
        words = {k: v[i] for k, v in rows.items()}
        with open(os.path.join(out, code + '.json'), 'w', encoding='utf-8', newline='\n') as f:
            json.dump(words, f, ensure_ascii=False, separators=(',', ':'))
    print(len(rows), 'phrases in', len(LANGS), 'languages')
